namespace bb::gui {
	thread_local void (*overlay_draw)() = nullptr;

	namespace {
		struct rect {
			int x = 0, y = 0, w = 0, h = 0;
		};

		struct rgb {
			int r, g, b;
		};

		constexpr rgb face       = { 212, 208, 200 };
		constexpr rgb light      = { 255, 255, 255 };
		constexpr rgb pale       = { 232, 230, 224 };
		constexpr rgb shadow     = { 128, 128, 128 };
		constexpr rgb dark       = { 64, 64, 64 };
		constexpr rgb black      = { 0, 0, 0 };
		constexpr rgb white      = { 255, 255, 255 };
		constexpr rgb highlight  = { 10, 36, 106 };
		constexpr rgb desktop_bg = { 58, 110, 165 };
		constexpr rgb grey_text  = { 128, 128, 128 };

		bool needs_draw = true;
		rect clip;
		int  overlay_combo = 0;

		rect intersect(rect a, rect b)
		{
			int x1 = a.x > b.x ? a.x : b.x, y1 = a.y > b.y ? a.y : b.y;
			int x2 = (a.x + a.w < b.x + b.w) ? a.x + a.w : b.x + b.w, y2 = (a.y + a.h < b.y + b.h) ? a.y + a.h : b.y + b.h;
			rect r;
			r.x = x1;
			r.y = y1;
			r.w = x2 > x1 ? x2 - x1 : 0;
			r.h = y2 > y1 ? y2 - y1 : 0;
			return r;
		}

		void clip_to(rect r)
		{
			clip = r;
			bb_viewport(r.x, r.y, r.w, r.h);
		}

		void color(rgb c)
		{
			bb_color(c.r, c.g, c.b);
		}

		void fill(int x, int y, int w, int h, rgb c)
		{
			if ((w <= 0) || (h <= 0)) {
				return;
			}
			color(c);
			bb_rect(x, y, w, h, 1);
		}

		void hline(int x, int y, int w, rgb c)
		{
			fill(x, y, w, 1, c);
		}

		void vline(int x, int y, int h, rgb c)
		{
			fill(x, y, 1, h, c);
		}

		void frame_box(int x, int y, int w, int h, rgb c)
		{
			hline(x, y, w, c);
			hline(x, y + h - 1, w, c);
			vline(x, y, h, c);
			vline(x + w - 1, y, h, c);
		}

		// The edge that makes things look raised or sunken, two pixels thick.
		void edge(int x, int y, int w, int h, bool sunken)
		{
			rgb outer_tl = sunken ? shadow : light, outer_br = sunken ? light : dark;
			rgb inner_tl = sunken ? dark : pale, inner_br = sunken ? pale : shadow;
			hline(x, y, w - 1, outer_tl);
			vline(x, y, h - 1, outer_tl);
			hline(x, y + h - 1, w, outer_br);
			vline(x + w - 1, y, h, outer_br);
			hline(x + 1, y + 1, w - 3, inner_tl);
			vline(x + 1, y + 1, h - 3, inner_tl);
			hline(x + 1, y + h - 2, w - 2, inner_br);
			vline(x + w - 2, y + 1, h - 2, inner_br);
		}

		// What is shown of a text: the & that marks a letter to press is not.
		void shown_text(const char* text, char* out, size_t size)
		{
			size_t n = 0;
			for (const char* p = text; p && *p && (n + 1 < size); p++) {
				if ((*p == '&') && p[1]) {
					continue;
				}
				out[n++] = *p;
			}
			out[n] = 0;
		}

		void text_at(gadget const& g, int x, int y, const char* text, rgb c)
		{
			if (!text || !*text) {
				return;
			}
			color(c);
			bb_gui_text(x, y, text, g.font, font_size(g));
		}

		void text_run(int x, int y, const char* text, int length, int font, int size, rgb c)
		{
			if (length <= 0) {
				return;
			}
			char* copy = static_cast<char*>(bb_malloc(size_t(length) + 1));
			memcpy(copy, text, size_t(length));
			copy[length] = 0;
			color(c);
			bb_gui_text(x, y, copy, font, size);
			bb_free(copy);
		}

		rgb text_color_of(gadget const& g)
		{
			return g.enabled ? black : grey_text;
		}

		// Draws what is selected in a text over the highlight, in white.
		void selected_text(int x, int y, const char* text, int length, int font, int size)
		{
			fill(x, y - 1, bb_gui_text_width(font, text, length, size), size + 2, highlight);
			text_run(x, y, text, length, font, size, white);
		}

		void arrow(int cx, int cy, int direction, rgb c)
		{
			// direction: 0 up, 1 down, 2 left, 3 right.
			for (int i = 0; i < 4; i++) {
				switch (direction) {
				case 0:
					hline(cx - i, cy - 2 + i, 2 * i + 1, c);
					break;
				case 1:
					hline(cx - i, cy + 2 - i, 2 * i + 1, c);
					break;
				case 2:
					vline(cx - 2 + i, cy - i, 2 * i + 1, c);
					break;
				default:
					vline(cx + 2 - i, cy - i, 2 * i + 1, c);
					break;
				}
			}
		}

		void scroll_bar(int x, int y, int w, int h, bool vertical, int position, int visible, int total, bool enabled)
		{
			fill(x, y, w, h, pale);
			int length = vertical ? h : w;
			// The arrows at both ends.
			for (int end = 0; end < 2; end++) {
				int bx = vertical ? x : (end ? x + w - bar_width : x), by = vertical ? (end ? y + h - bar_width : y) : y;
				int bw = vertical ? w : bar_width, bh = vertical ? bar_width : h;
				fill(bx, by, bw, bh, face);
				edge(bx, by, bw, bh, false);
				arrow(bx + bw / 2, by + bh / 2, vertical ? end : 2 + end, enabled ? black : grey_text);
			}
			if (enabled && (total > visible)) {
				int start, size;
				scroll_thumb(position, visible, total, length, &start, &size);
				int tx = vertical ? x : x + start, ty = vertical ? y + start : y;
				int tw = vertical ? w : size, th = vertical ? size : h;
				fill(tx, ty, tw, th, face);
				edge(tx, ty, tw, th, false);
			}
		}

		void draw_icon(gadget const& g, int icon, int x, int y)
		{
			icon_strip* strip = strip_of(g.strip);
			if (strip && (icon >= 0) && (icon < strip->count)) {
				bb_draw_image_rect(strip->image, x, y, icon * strip->size, 0, strip->size, strip->size, 0);
			}
		}

		void draw_children(int handle, int ox, int oy, rect parent_clip);

		////////////////////////////////////////////////////////////////////
		// The gadgets
		////////////////////////////////////////////////////////////////////
		void draw_label(gadget const& g, int x, int y)
		{
			fill(x, y, g.w, g.h, face);
			switch (g.style & 3) {
			case 1:
				frame_box(x, y, g.w, g.h, dark);
				break;
			case 2:
				edge(x, y, g.w, g.h, false);
				break;
			case 3:
				edge(x, y, g.w, g.h, true);
				break;
			default:
				break;
			}
			char text[1024];
			shown_text(g.text, text, sizeof(text));
			// Lines are broken where the text is longer than the label is wide.
			int size = font_size(g), room = g.w - 6, row = 0;
			rect saved = clip;
			clip_to(intersect(saved, { x, y, g.w, g.h }));
			for (const char* p = text; *p;) {
				int line = 0;
				while (p[line] && (p[line] != '\r') && (p[line] != '\n')) {
					line++;
				}
				int cols = fit_chars(g, p, line, room);
				if (cols < 1) {
					cols = 1;
				}
				int n = 0;
				while (p[n] && (p[n] != '\r') && (p[n] != '\n') && (n < cols)) {
					n++;
				}
				if ((n == cols) && p[n] && (p[n] != '\r') && (p[n] != '\n')) {
					int cut = n;
					while ((cut > 0) && (p[cut] != ' ')) {
						cut--;
					}
					if (cut > 0) {
						n = cut;
					}
				}
				text_run(x + 3, y + 3 + row * (size + 2), p, n, g.font, size, text_color_of(g));
				p += n;
				if ((*p == '\r') || (*p == '\n') || (*p == ' ')) {
					p++;
				}
				row++;
			}
			clip_to(saved);
		}

		void draw_button(int handle, gadget const& g, int x, int y)
		{
			char text[1024];
			shown_text(g.text, text, sizeof(text));
			int  size = font_size(g), len = int(strlen(text));
			bool pressed = (ui.pressed == handle) && (ui.hover == handle);
			if ((g.style == 2) || (g.style == 3)) {
				// Check boxes and radio buttons: the box, then the text next to it.
				fill(x, y, g.w, g.h, face);
				int bx = x, by = y + (g.h - 13) / 2;
				if (g.style == 2) {
					fill(bx, by, 13, 13, g.enabled ? white : face);
					edge(bx, by, 13, 13, true);
					if (g.state) {
						color(g.enabled ? black : grey_text);
						bb_line(bx + 3, by + 6, bx + 5, by + 8);
						bb_line(bx + 5, by + 8, bx + 10, by + 3);
						bb_line(bx + 3, by + 7, bx + 5, by + 9);
						bb_line(bx + 5, by + 9, bx + 10, by + 4);
					}
				} else {
					color(g.enabled ? white : face);
					bb_oval(bx, by, 13, 13, 1);
					color(shadow);
					bb_oval(bx, by, 13, 13, 0);
					if (g.state) {
						color(g.enabled ? black : grey_text);
						bb_oval(bx + 4, by + 4, 5, 5, 1);
					}
				}
				text_at(g, x + 19, y + (g.h - size) / 2, text, text_color_of(g));
				if (ui.focus == handle) {
					frame_box(x + 17, y + (g.h - size) / 2 - 2, text_width(g, text, len) + 4, size + 4, shadow);
				}
				return;
			}
			fill(x, y, g.w, g.h, face);
			if (g.style == 4) {
				frame_box(x, y, g.w, g.h, black);
				edge(x + 1, y + 1, g.w - 2, g.h - 2, pressed);
			} else {
				edge(x, y, g.w, g.h, pressed);
			}
			int shift = pressed ? 1 : 0;
			rect saved = clip;
			clip_to(intersect(saved, { x + 3, y + 3, g.w - 6, g.h - 6 }));
			text_at(g, x + (g.w - text_width(g, text, len)) / 2 + shift, y + (g.h - size) / 2 + shift, text, text_color_of(g));
			clip_to(saved);
			if (ui.focus == handle) {
				frame_box(x + 4, y + 4, g.w - 8, g.h - 8, shadow);
			}
		}

		// Whether the cursor is shown right now: it blinks while the gadget is used.
		bool blink_on()
		{
			return ((bb_millisecs() / 500) & 1) == 0;
		}

		void draw_text_field(int handle, gadget const& g, int x, int y)
		{
			fill(x, y, g.w, g.h, g.enabled ? white : face);
			edge(x, y, g.w, g.h, true);
			int size = font_size(g), tx = x + 3 - g.scroll_x, ty = y + (g.h - size) / 2;
			rect saved = clip;
			clip_to(intersect(saved, { x + 2, y + 2, g.w - 4, g.h - 4 }));
			int         length = g.text ? int(strlen(g.text)) : 0;
			char*       shown  = static_cast<char*>(bb_malloc(size_t(length) + 1));
			for (int i = 0; i < length; i++) {
				shown[i] = (g.style & 1) ? '*' : g.text[i];
			}
			shown[length] = 0;
			int lo = g.caret < g.anchor ? g.caret : g.anchor, hi = g.caret < g.anchor ? g.anchor : g.caret;
			if (lo > length) {
				lo = length;
			}
			if (hi > length) {
				hi = length;
			}
			text_run(tx, ty, shown, length, g.font, size, text_color_of(g));
			if ((ui.focus == handle) && (hi > lo)) {
				selected_text(tx + field_x(g, lo), ty, shown + lo, hi - lo, g.font, size);
			}
			if ((ui.focus == handle) && (hi == lo) && blink_on()) {
				vline(tx + field_x(g, g.caret), ty - 1, size + 2, black);
			}
			bb_free(shown);
			clip_to(saved);
		}

		bool format_at(gadget const& g, int pos, rgb* c, int* flags)
		{
			for (uint32_t i = 0; i < g.formats.size; i++) {
				text_format const& f = g.formats[i];
				if ((pos >= f.pos) && (pos < f.pos + f.len)) {
					*c     = { f.r, f.g, f.b };
					*flags = f.flags;
					return true;
				}
			}
			return false;
		}

		void draw_text_area(int handle, gadget const& g, int x, int y)
		{
			rgb back = g.has_back ? rgb { g.back_color[0], g.back_color[1], g.back_color[2] } : white;
			rgb base = g.has_text_color ? rgb { g.text_color[0], g.text_color[1], g.text_color[2] } : black;
			if (!g.enabled) {
				back = face;
			}
			fill(x, y, g.w, g.h, back);
			edge(x, y, g.w, g.h, true);
			int cx, cy, cw, ch;
			content_rect(g, &cx, &cy, &cw, &ch);
			rect saved = clip;
			clip_to(intersect(saved, { x + cx, y + cy, cw, ch }));
			int                 size = font_size(g), rh = row_height(g);
			buffer<visual_line> lines;
			build_lines(g, lines);
			int lo = g.caret < g.anchor ? g.caret : g.anchor, hi = g.caret < g.anchor ? g.anchor : g.caret;
			int shown_x = (g.style & 1) ? 0 : g.scroll_x;
			for (int row = g.scroll_y; (row < int(lines.size)) && ((row - g.scroll_y) * rh < ch); row++) {
				visual_line const& line = lines[uint32_t(row)];
				int                ty   = y + cy + (row - g.scroll_y) * rh + 1;
				// Runs of characters that look alike are drawn at once.
				int i = 0;
				while (i < line.length) {
					rgb  c     = base;
					int  flags = 0;
					bool formatted = format_at(g, line.start + i, &c, &flags);
					bool selected = (line.start + i >= lo) && (line.start + i < hi) && (ui.focus == handle || true);
					int  j     = i + 1;
					while (j < line.length) {
						rgb  c2     = base;
						int  flags2 = 0;
						bool f2     = format_at(g, line.start + j, &c2, &flags2);
						bool s2     = (line.start + j >= lo) && (line.start + j < hi);
						if ((f2 != formatted) || (f2 && ((c2.r != c.r) || (c2.g != c.g) || (c2.b != c.b) || (flags2 != flags))) || (s2 != selected)) {
							break;
						}
						j++;
					}
					// Tabs are as wide as the tab stops of the gadget.
					const char* run = g.text + line.start + i;
					int         tx  = x + cx - shown_x + text_width(g, g.text + line.start, i);
					int         run_width = text_width(g, run, j - i);
					if (selected && (ui.focus == handle)) {
						selected_text(tx, ty, run, j - i, g.font, size);
					} else {
						text_run(tx, ty, run, j - i, g.font, size, g.enabled ? c : grey_text);
						if (flags & 1) {
							text_run(tx + 1, ty, run, j - i, g.font, size, g.enabled ? c : grey_text);
						}
						if (flags & 4) {
							hline(tx, ty + size, run_width, c);
						}
						if (flags & 8) {
							hline(tx, ty + size / 2, run_width, c);
						}
					}
					i = j;
				}
				// The cursor.
				if ((ui.focus == handle) && (hi == lo) && blink_on() && (g.caret >= line.start) && (g.caret <= line.start + line.length)) {
					bool wrapped_end = (g.style & 1) && (g.caret == line.start + line.length) && (row + 1 < int(lines.size))
					                && (lines[uint32_t(row + 1)].start == g.caret);
					if (!wrapped_end) {
						vline(x + cx - shown_x + text_width(g, g.text + line.start, g.caret - line.start), ty - 1, size + 2, base);
					}
				}
			}
			clip_to(saved);
			// The scroll bar.
			int sx, sy, sw, sh;
			scroll_rect(g, &sx, &sy, &sw, &sh);
			scroll_bar(x + sx, y + sy, sw, sh, true, g.scroll_y, visible_rows(g), int(lines.size), g.enabled);
			if (has_hbar(g)) {
				int hx, hy, hw, hh;
				hscroll_rect(g, &hx, &hy, &hw, &hh);
				scroll_bar(x + hx, y + hy, hw, hh, false, g.scroll_x, hw, longest_line_width(g), g.enabled);
				fill(x + sx, y + hy, sw, hh, face); // The corner between both bars.
			}
			lines.release();
		}

		void draw_list_row_icon(gadget const& g, int icon, int x, int y, int rh)
		{
			icon_strip* strip = strip_of(g.strip);
			if (strip && (icon >= 0)) {
				draw_icon(g, icon, x, y + (rh - strip->size) / 2);
			}
		}

		void draw_list_box(int handle, gadget const& g, int x, int y)
		{
			(void)handle;
			fill(x, y, g.w, g.h, g.enabled ? white : face);
			edge(x, y, g.w, g.h, true);
			int cx, cy, cw, ch;
			content_rect(g, &cx, &cy, &cw, &ch);
			rect saved = clip;
			clip_to(intersect(saved, { x + cx, y + cy, cw, ch }));
			int rh = row_height(g), size = font_size(g);
			icon_strip* strip = strip_of(g.strip);
			int         indent = strip ? strip->size + 4 : 0;
			for (int i = g.scroll; (i < int(g.items.size)) && ((i - g.scroll) * rh < ch); i++) {
				int ry = y + cy + (i - g.scroll) * rh;
				bool selected = (i == g.selected);
				if (selected) {
					fill(x + cx, ry, cw, rh, highlight);
				}
				draw_list_row_icon(g, g.items[uint32_t(i)].icon, x + cx + 2, ry, rh);
				text_at(g, x + cx + 2 + indent, ry + (rh - size) / 2, g.items[uint32_t(i)].text, selected ? white : text_color_of(g));
			}
			clip_to(saved);
			if (total_rows(g) > visible_rows(g)) {
				int sx, sy, sw, sh;
				scroll_rect(g, &sx, &sy, &sw, &sh);
				scroll_bar(x + sx, y + sy, sw, sh, true, g.scroll, visible_rows(g), total_rows(g), g.enabled);
			}
		}

		void draw_combo_box(int handle, gadget const& g, int x, int y)
		{
			fill(x, y, g.w, g.h, g.enabled ? white : face);
			edge(x, y, g.w, g.h, true);
			int size = font_size(g);
			if ((g.selected >= 0) && (g.selected < int(g.items.size))) {
				icon_strip* strip = strip_of(g.strip);
				int         indent = strip ? strip->size + 4 : 0;
				rect        saved  = clip;
				clip_to(intersect(saved, { x + 2, y + 2, g.w - 4 - bar_width, g.h - 4 }));
				draw_list_row_icon(g, g.items[uint32_t(g.selected)].icon, x + 4, y, g.h);
				text_at(g, x + 4 + indent, y + (g.h - size) / 2, g.items[uint32_t(g.selected)].text, text_color_of(g));
				clip_to(saved);
			}
			int bx = x + g.w - 2 - bar_width, by = y + 2, bh = g.h - 4;
			fill(bx, by, bar_width, bh, face);
			edge(bx, by, bar_width, bh, ui.combo == handle);
			arrow(bx + bar_width / 2, by + bh / 2, 1, g.enabled ? black : grey_text);
			if (ui.combo == handle) {
				overlay_combo = handle;
			}
		}

		void draw_combo_list(int handle)
		{
			gadget* g = gadget_of(handle);
			if (!g) {
				return;
			}
			int ax, ay;
			absolute_position(handle, &ax, &ay);
			int rh = row_height(*g), rows = int(g->items.size) < 8 ? int(g->items.size) : 8;
			int lx = ax, ly = ay + g->h, lw = g->w, lh = rows * rh + 4;
			fill(lx, ly, lw, lh, white);
			frame_box(lx, ly, lw, lh, black);
			icon_strip* strip  = strip_of(g->strip);
			int         indent = strip ? strip->size + 4 : 0;
			for (int i = g->scroll; (i < int(g->items.size)) && (i - g->scroll < rows); i++) {
				int ry = ly + 2 + (i - g->scroll) * rh;
				if (i == g->selected) {
					fill(lx + 2, ry, lw - 4, rh, highlight);
				}
				draw_list_row_icon(*g, g->items[uint32_t(i)].icon, lx + 4, ry, rh);
				text_at(*g, lx + 4 + indent, ry + (rh - font_size(*g)) / 2, g->items[uint32_t(i)].text, i == g->selected ? white : black);
			}
		}

		void draw_tabber(gadget const& g, int x, int y)
		{
			int tx, ty, tw, th;
			tab_client_rect(g, &tx, &ty, &tw, &th);
			fill(x, y + tab_height - 2, g.w, g.h - tab_height + 2, face);
			edge(x, y + tab_height - 2, g.w, g.h - tab_height + 2, false);
			int size = font_size(g);
			icon_strip* strip = strip_of(g.strip);
			for (int i = 0; i < int(g.items.size); i++) {
				int rx, ry, rw, rh;
				tab_rect(g, i, &rx, &ry, &rw, &rh);
				bool on = (i == g.selected);
				int  lift = on ? 0 : 2;
				fill(x + rx, y + ry + lift, rw, rh - lift, face);
				hline(x + rx, y + ry + lift, rw, light);
				vline(x + rx, y + ry + lift, rh - lift, light);
				vline(x + rx + rw - 1, y + ry + lift, rh - lift, dark);
				if (on) {
					hline(x + rx + 1, y + tab_height - 2, rw - 2, face);
					hline(x + rx + 1, y + tab_height - 1, rw - 2, face);
				}
				int at = x + rx + 10;
				if (strip && (g.items[uint32_t(i)].icon >= 0)) {
					draw_icon(g, g.items[uint32_t(i)].icon, at, y + ry + lift + (rh - lift - strip->size) / 2);
					at += strip->size + 4;
				}
				text_at(g, at, y + ry + lift + (rh - lift - size) / 2, g.items[uint32_t(i)].text, text_color_of(g));
			}
		}

		void draw_tree_view(int handle, gadget const& g, int x, int y)
		{
			(void)handle;
			fill(x, y, g.w, g.h, g.enabled ? white : face);
			edge(x, y, g.w, g.h, true);
			int cx, cy, cw, ch;
			content_rect(g, &cx, &cy, &cw, &ch);
			rect saved = clip;
			clip_to(intersect(saved, { x + cx, y + cy, cw, ch }));
			buffer<tree_row> rows;
			build_tree_rows(g, rows);
			int         rh = row_height(g), size = font_size(g);
			icon_strip* strip = strip_of(g.strip);
			for (int i = g.scroll; (i < int(rows.size)) && ((i - g.scroll) * rh < ch); i++) {
				node* n  = node_of(rows[uint32_t(i)].node);
				int   ry = y + cy + (i - g.scroll) * rh;
				int   rx = x + cx + 4 + rows[uint32_t(i)].depth * 16;
				if (!n) {
					continue;
				}
				if (n->kids.size) {
					int ey = ry + rh / 2 - 4;
					fill(rx, ey, 9, 9, white);
					frame_box(rx, ey, 9, 9, shadow);
					hline(rx + 2, ey + 4, 5, black);
					if (!n->expanded) {
						vline(rx + 4, ey + 2, 5, black);
					}
				}
				rx += 14;
				if (strip && (n->icon >= 0)) {
					draw_icon(g, n->icon, rx, ry + (rh - strip->size) / 2);
					rx += strip->size + 4;
				}
				bool selected = rows[uint32_t(i)].node == g.selected_node;
				int  len      = n->text ? int(strlen(n->text)) : 0;
				if (selected) {
					fill(rx - 2, ry, text_width(g, n->text, len) + 4, rh, highlight);
				}
				text_at(g, rx, ry + (rh - size) / 2, n->text, selected ? white : text_color_of(g));
			}
			clip_to(saved);
			if (int(rows.size) > visible_rows(g)) {
				int sx, sy, sw, sh;
				scroll_rect(g, &sx, &sy, &sw, &sh);
				scroll_bar(x + sx, y + sy, sw, sh, true, g.scroll, visible_rows(g), int(rows.size), g.enabled);
			}
			rows.release();
		}

		void draw_slider(gadget const& g, int x, int y)
		{
			bool horizontal = slider_horizontal(g);
			int  visible = g.range_visible > 0 ? g.range_visible : 1, limit = slider_limit(g);
			scroll_bar(x, y, g.w, g.h, !horizontal, g.state, visible, limit + visible, g.enabled && (g.range_total > 1));
		}

		void draw_prog_bar(gadget const& g, int x, int y)
		{
			fill(x, y, g.w, g.h, face);
			edge(x, y, g.w, g.h, true);
			int w = int(float(g.w - 4) * g.progress);
			fill(x + 2, y + 2, w, g.h - 4, highlight);
		}

		void draw_panel(gadget const& g, int x, int y)
		{
			rgb c = g.has_color ? rgb { g.color[0], g.color[1], g.color[2] } : face;
			fill(x, y, g.w, g.h, c);
			if (g.image) {
				bb_tile_image(g.image, x, y, 0);
			}
			if (g.style & 1) {
				edge(x, y, g.w, g.h, true);
			}
		}

		void draw_canvas(gadget const& g, int x, int y)
		{
			fill(x, y, g.w, g.h, black);
			if (g.image) {
				bb_draw_block(g.image, x, y, 0);
			}
		}

		void draw_tool_bar(int handle, gadget const& g, int x, int y)
		{
			fill(x, y, g.w, g.h, face);
			hline(x, y + g.h - 1, g.w, shadow);
			icon_strip* strip = strip_of(g.strip);
			if (!strip) {
				return;
			}
			for (int i = 0; i < strip->count; i++) {
				int index = tool_button_index(g, i);
				if (index < 0) {
					continue;
				}
				int bx, by, bw, bh;
				tool_button_rect(g, i, &bx, &by, &bw, &bh);
				bool enabled = index < int(g.tool_enabled.size) ? g.tool_enabled[uint32_t(index)] != 0 : true;
				bool hot = (ui.hover == handle) && (g.tool_hot == index) && enabled;
				bool down = hot && (ui.pressed == handle);
				if (hot) {
					edge(x + bx, y + by, bw, bh, down);
				}
				int dx = x + bx + 4 + (down ? 1 : 0), dy = y + by + 4 + (down ? 1 : 0);
				draw_icon(g, i, dx, dy);
				if (!enabled) {
					// A grid of the color of the bar over the icon makes it look dimmed.
					for (int row = 0; row < strip->size; row += 2) {
						hline(dx, dy + row, strip->size, face);
					}
				}
			}
		}

		////////////////////////////////////////////////////////////////////
		// Windows
		////////////////////////////////////////////////////////////////////
		// The glyphs are made for boxes of 18 by 16, and are centered in smaller ones.
		void title_box(int x, int y, int glyph, int width = 18, int height = 16)
		{
			fill(x, y, width, height, face);
			edge(x, y, width, height, false);
			x += (width - 18) / 2;
			y += (height - 16) / 2;
			switch (glyph) {
			case 0: // Close
				color(black);
				bb_line(x + 5, y + 4, x + 12, y + 11);
				bb_line(x + 6, y + 4, x + 13, y + 11);
				bb_line(x + 12, y + 4, x + 5, y + 11);
				bb_line(x + 13, y + 4, x + 6, y + 11);
				break;
			case 1: // Maximize
				frame_box(x + 4, y + 3, 10, 9, black);
				hline(x + 4, y + 4, 10, black);
				break;
			default: // Minimize
				fill(x + 4, y + 10, 8, 2, black);
				break;
			}
		}

		void draw_window_frame(gadget const& g, int x, int y, bool active)
		{
			fill(x, y, g.w, g.h, face);
			if (g.style & 1) {
				edge(x, y, g.w, g.h, false);
				int frame = (g.style & 2) ? frame_width : 3;
				fill(x + frame, y + frame, g.w - 2 * frame, title_bar_height(g), active ? highlight : shadow);
				char text[1024];
				shown_text(g.text, text, sizeof(text));
				int size = 12;
				rect saved = clip;
				int  close_x, max_x, min_x, by;
				int  buttons = window_buttons(g, &close_x, &max_x, &min_x, &by);
				clip_to(intersect(saved, { x + frame, y + frame, g.w - 2 * frame - buttons * title_box_width(g), title_bar_height(g) }));
				text_run(x + frame + 4, y + frame + (title_bar_height(g) - size) / 2, text, int(strlen(text)), 0, size, white);
				clip_to(saved);
				if (buttons) {
					int bw = title_box_width(g), bh = title_box_height(g);
					title_box(x + close_x, y + by, 0, bw, bh);
					if (buttons == 3) {
						title_box(x + max_x, y + by, 1, bw, bh);
						title_box(x + min_x, y + by, 2, bw, bh);
					}
				}
			} else {
				frame_box(x, y, g.w, g.h, dark);
			}
			// The menu bar.
			menu* root = menu_of(g.menu);
			if (g.style & 4) {
				// The bar is there with or without menus in it, as it is on Windows: a line under it sets it apart.
				int handle = handle_of(&g);
				int bx, by, bw, bh;
				menu_bar_rect(handle, 0, &bx, &by, &bw, &bh);
				fill(x + bx, y + by, g.w - 2 * bx, bh, face);
				hline(x + bx, y + by + bh - 2, g.w - 2 * bx, shadow);
				hline(x + bx, y + by + bh - 1, g.w - 2 * bx, light);
				for (uint32_t i = 0; root && (i < root->kids.size); i++) {
					menu* m = menu_of(root->kids[i]);
					menu_bar_rect(handle, int(i), &bx, &by, &bw, &bh);
					bool open = (ui.menu_window == handle) && ui.menu_path.size && (ui.menu_path[0] == root->kids[i]);
					if (open) {
						edge(x + bx, y + by, bw, bh, true);
					}
					char text[256];
					shown_text(m ? m->text : "", text, sizeof(text));
					color(m && m->enabled ? black : grey_text);
					bb_gui_text(x + bx + 8 + (open ? 1 : 0), y + by + (bh - 12) / 2 + (open ? 1 : 0), text, 0, 12);
				}
			}
			// The status bar.
			if (g.style & 8) {
				int frame = (g.style & 1) ? ((g.style & 2) ? frame_width : 3) : 1;
				int sy = y + g.h - frame - status_height;
				fill(x + frame, sy, g.w - 2 * frame, status_height, face);
				edge(x + frame, sy + 1, g.w - 2 * frame, status_height - 1, true);
				text_run(x + frame + 6, sy + (status_height - 12) / 2 + 1, g.status ? g.status : "", g.status ? int(strlen(g.status)) : 0, 0, 12, black);
			}
		}

		void draw_gadget(int handle, int x, int y, rect parent_clip)
		{
			gadget* g = gadget_of(handle);
			if (!g || !g->visible) {
				return;
			}
			rect self = intersect(parent_clip, { x, y, g->w, g->h });
			if (!self.w || !self.h) {
				return;
			}
			clip_to(self);
			switch (g->kind) {
			case K_LABEL:
				draw_label(*g, x, y);
				break;
			case K_BUTTON:
				draw_button(handle, *g, x, y);
				break;
			case K_TEXTFIELD:
				draw_text_field(handle, *g, x, y);
				break;
			case K_TEXTAREA:
				draw_text_area(handle, *g, x, y);
				break;
			case K_LISTBOX:
				draw_list_box(handle, *g, x, y);
				break;
			case K_COMBOBOX:
				draw_combo_box(handle, *g, x, y);
				break;
			case K_TABBER:
				draw_tabber(*g, x, y);
				break;
			case K_TREEVIEW:
				draw_tree_view(handle, *g, x, y);
				break;
			case K_SLIDER:
				draw_slider(*g, x, y);
				break;
			case K_PROGBAR:
				draw_prog_bar(*g, x, y);
				break;
			case K_PANEL:
				draw_panel(*g, x, y);
				break;
			case K_CANVAS:
				draw_canvas(*g, x, y);
				break;
			case K_TOOLBAR:
				draw_tool_bar(handle, *g, x, y);
				break;
			default:
				break;
			}
			if ((g->kind == K_PANEL) || (g->kind == K_TABBER) || (g->kind == K_CANVAS)) {
				int cx, cy, cw, ch;
				client_rect(handle, &cx, &cy, &cw, &ch);
				draw_children(handle, x + cx, y + cy, intersect(self, { x + cx, y + cy, cw, ch }));
			}
		}

		void draw_children(int handle, int ox, int oy, rect parent_clip)
		{
			gadget* g = gadget_of(handle);
			if (!g) {
				return;
			}
			for (uint32_t i = 0; i < g->kids.size; i++) {
				gadget* kid = gadget_of(g->kids[i]);
				if (kid) {
					draw_gadget(g->kids[i], ox + kid->x, oy + kid->y, parent_clip);
				}
			}
		}

		void draw_window(int handle, rect screen)
		{
			gadget* g = gadget_of(handle);
			if (!g || !g->visible) {
				return;
			}
			int x = g->x, y = g->y;
			if (g->minimized) {
				int mw, mh;
				minimized_rect(handle, &x, &y, &mw, &mh);
				clip_to(screen);
				fill(x, y, mw, mh, handle == active_window() ? highlight : shadow);
				edge(x, y, mw, mh, false);
				char text[1024];
				shown_text(g->text, text, sizeof(text));
				clip_to(intersect(screen, { x + 2, y, mw - 4, mh }));
				text_run(x + 6, y + (mh - 12) / 2, text, int(strlen(text)), 0, 12, white);
				return;
			}
			// The window is drawn into a picture of its own, at its own origin, which is then put on the desktop where the window is.
			// A native window (BlitzPlus) shows that picture by itself instead.
			int w = g->w > 0 ? g->w : 1, h = g->h > 0 ? g->h : 1;
			if (g->picture && ((g->picture_w != w) || (g->picture_h != h))) {
				bb_free_image(g->picture);
				g->picture = 0;
			}
			if (!g->picture) {
				offscreen_hold hold;
				g->picture   = bb_create_image(w, h, 1);
				g->picture_w = w;
				g->picture_h = h;
			}
			int saved = bb_graphics_buffer();
			bb_set_buffer(bb_image_buffer(g->picture, 0));
			rect whole = { 0, 0, w, h };
			clip_to(whole);
			draw_window_frame(*g, 0, 0, handle == active_window());
			int cx, cy, cw, ch;
			client_rect(handle, &cx, &cy, &cw, &ch);
			draw_children(handle, cx, cy, intersect(whole, { cx, cy, cw, ch }));
			bb_set_buffer(saved);
			clip_to(intersect(screen, { x, y, w, h }));
			bb_draw_block(g->picture, x, y, 0);
		}

		void draw_menu_popups(rect screen)
		{
			clip_to(screen);
			int window = ui.menu_window;
			for (uint32_t level = 0; window && (level < ui.menu_path.size); level++) {
				int px, py, pw, ph;
				menu_popup_rect(window, int(level), &px, &py, &pw, &ph);
				gadget* g = gadget_of(window);
				menu*   m = menu_of(ui.menu_path[level]);
				if (!g || !m) {
					break;
				}
				px += g->x;
				py += g->y;
				fill(px, py, pw, ph, face);
				edge(px, py, pw, ph, false);
				int rh = menu_row_height();
				for (uint32_t i = 0; i < m->kids.size; i++) {
					menu* kid = menu_of(m->kids[i]);
					int   ry  = py + 2 + int(i) * rh;
					if (!kid) {
						continue;
					}
					if (!kid->text || !*kid->text) {
						hline(px + 4, ry + rh / 2, pw - 8, shadow);
						hline(px + 4, ry + rh / 2 + 1, pw - 8, light);
						continue;
					}
					bool open = (level + 1 < ui.menu_path.size) && (ui.menu_path[level + 1] == m->kids[i]);
					if (open) {
						fill(px + 2, ry, pw - 4, rh, highlight);
					}
					char text[256];
					shown_text(kid->text, text, sizeof(text));
					rgb c = !kid->enabled ? grey_text : (open ? white : black);
					color(c);
					bb_gui_text(px + 24, ry + (rh - 12) / 2, text, 0, 12);
					if (kid->checked) {
						color(c);
						bb_line(px + 8, ry + rh / 2, px + 11, ry + rh / 2 + 3);
						bb_line(px + 11, ry + rh / 2 + 3, px + 16, ry + rh / 2 - 3);
						bb_line(px + 8, ry + rh / 2 + 1, px + 11, ry + rh / 2 + 4);
						bb_line(px + 11, ry + rh / 2 + 4, px + 16, ry + rh / 2 - 2);
					}
					if (kid->kids.size) {
						arrow(px + pw - 10, ry + rh / 2, 3, c);
					}
				}
			}
		}
	} // namespace

	void dirty()
	{
		needs_draw = true;
	}

	void ensure_graphics()
	{
		if (!bb_graphics_width()) {
			bb_graphics(1024, 768, 32, 3);
		}
	}

	namespace {
		// Tool tips show after the mouse rested on a button of a toolbar for a moment.
		int  tip_gadget = 0, tip_index = -1, tip_since = 0;
		bool tip_shown = false;

		// Which button of which toolbar has a tip right now, or false.
		bool tip_wanted(int* handle, int* index)
		{
			gadget* g = gadget_of(ui.hover);
			if (!g || (g->kind != K_TOOLBAR) || !g->tips || (g->tool_hot < 0) || ui.pressed || ui.modal) {
				return false;
			}
			*handle = ui.hover;
			*index  = g->tool_hot;
			return true;
		}

		// The piece between commas that is for a button, counting only buttons and not spaces.
		bool tip_text(gadget const& g, int index, char* out, int size)
		{
			const char* at = g.tips;
			for (int i = 0; i < index; i++) {
				at = strchr(at, ',');
				if (!at) {
					return false;
				}
				at++;
			}
			const char* end = strchr(at, ',');
			int         len = end ? int(end - at) : int(strlen(at));
			if ((len <= 0) || (len >= size)) {
				return false;
			}
			memcpy(out, at, size_t(len));
			out[len] = 0;
			return true;
		}

		void draw_tool_tip(int screen_w)
		{
			int handle, index;
			gadget* g = gadget_of(tip_gadget);
			char    text[256];
			if (!tip_shown || !tip_wanted(&handle, &index) || (handle != tip_gadget) || (index != tip_index) || !g || !tip_text(*g, index, text, sizeof(text))) {
				return;
			}
			int ax, ay;
			absolute_position(handle, &ax, &ay);
			icon_strip* strip = strip_of(g->strip);
			for (int i = 0; strip && (i < strip->count); i++) {
				if (tool_button_index(*g, i) != index) {
					continue;
				}
				int bx, by, bw, bh;
				tool_button_rect(*g, i, &bx, &by, &bw, &bh);
				int size = font_size(*g), w = text_width(*g, text, int(strlen(text))) + 8, h = size + 6;
				int x = ax + bx, y = ay + by + bh + 2;
				x         = x + w > screen_w ? screen_w - w : x;
				x         = x < 0 ? 0 : x;
				fill(x, y, w, h, { 255, 255, 225 });
				frame_box(x, y, w, h, black);
				text_at(*g, x + 4, y + 3, text, black);
			}
		}

		// Whether what is shown changed because of tips, which it did when one appears or goes.
		bool tips_changed()
		{
			int  handle = 0, index = -1;
			bool wanted = tip_wanted(&handle, &index);
			if (!wanted || (handle != tip_gadget) || (index != tip_index)) {
				bool was     = tip_shown;
				tip_gadget   = wanted ? handle : 0;
				tip_index    = wanted ? index : -1;
				tip_since    = bb_millisecs();
				tip_shown    = false;
				return was;
			}
			if (!tip_shown && (bb_millisecs() - tip_since >= 500)) {
				tip_shown = true;
				return true;
			}
			return false;
		}
	} // namespace

	void render()
	{
		int w = bb_graphics_width(), h = bb_graphics_height();
		if (!w || !h) {
			return;
		}
		needs_draw    = false;
		overlay_combo = 0;
		bb_set_buffer(bb_back_buffer());
		bb_origin(0, 0);
		rect screen = { 0, 0, w, h };
		clip_to(screen);
		bb_clscolor(desktop_bg.r, desktop_bg.g, desktop_bg.b);
		bb_cls();
		gadget* desk = gadget_of(desktop_handle());
		for (uint32_t i = 0; desk && (i < desk->kids.size); i++) {
			draw_window(desk->kids[i], screen);
		}
		// Whatever is open is on top of everything.
		clip_to(screen);
		if (overlay_combo) {
			draw_combo_list(overlay_combo);
		}
		draw_menu_popups(screen);
		clip_to(screen);
		draw_tool_tip(w);
		if (overlay_draw) {
			overlay_draw();
		}
		bb_flip(0);
	}

	// Called whenever the program waits or asks for input: what changed is shown.
	void update()
	{
		if (!gui_used || !bb_gui_live()) {
			return;
		}
		// The cursor of what has the focus blinks.
		static thread_local int last_phase = -1;
		gadget*    f          = gadget_of(ui.focus);
		if (f && ((f->kind == K_TEXTFIELD) || (f->kind == K_TEXTAREA))) {
			int phase = (bb_millisecs() / 500) & 1;
			if (phase != last_phase) {
				last_phase = phase;
				needs_draw = true;
			}
		}
		if (tips_changed()) {
			needs_draw = true;
		}
		if (needs_draw) {
			render();
		}
	}
} // namespace bb::gui

extern "C" void bb_gui_idle(void)
{
	bb::gui::update();
}
